class _c_Fixed(_mx_sys.BaseSpace):

    def __init__(self, parent):

        # modelx variables
        self._space = self
        self._parent = parent
        self._model = parent._model
        self._name = "Fixed"


        self._mx_spaces = {

        }

        self._mx_cells = {}     # Populated on calling self._cells
        self._mx_is_cells_set = False
        self._mx_itemspaces = {}
        self._mx_roots = []     # Dynamic Space only

        # Cache variables
        self._v_Payment = None
        self._has_Payment = False
        self._v_Balance = {}

    def _mx_assign_refs(self, io_data, pickle_data):

        # Reference assignment
        self.Principal = 100000
        self.Term = 30
        self.Rate = 0.03
        self.SampleString = 'Date 2053-01-01'

    def _mx_copy_refs(self, base, base_root):

        # Reference assignment
        self.Principal = base.Principal
        self.Term = base.Term
        self.Rate = base.Rate
        self.SampleString = base.SampleString

    def _f_Payment(self):
        return self.Principal * self.Rate * (1+self.Rate)**self.Term / ((1+self.Rate)**self.Term - 1)

    def _f_Balance(self, t):

        if t > 0:
            return self.Balance(t-1) * (1+self.Rate) - self.Payment()
        else:
            return self.Principal


    def Payment(self):
        if self._has_Payment:
            return self._v_Payment
        else:
            val = self._v_Payment = self._f_Payment()
            self._has_Payment = True
            return val

    def Balance(self, t):
        if t in self._v_Balance:
            return self._v_Balance[t]
        else:
            val = self._f_Balance(t)
            self._v_Balance[t] = val
            return val



    def _mx_copy_params(self, other):
        # Parameter assignment
        other.Term = self.Term
        other.Rate = self.Rate

    @staticmethod
    def _mx_assign_params(_mx_space, Term, Rate):
        # Parameter assignment
        _mx_space.Term = Term
        _mx_space.Rate = Rate

    def __call__(self, Term, Rate):
        _mx_key = (Term, Rate)
        if _mx_key in self._mx_itemspaces:
            return self._mx_itemspaces[_mx_key]
        else:
            _mx_base = self
            _mx_root = _mx_base.__class__(self)
            for _mx_s, _mx_b in zip(_mx_root._mx_walk(), _mx_base._mx_walk()):
                _mx_s._mx_copy_refs(_mx_b, _mx_base)
                for _mx_r in self._mx_roots:
                    _mx_r._mx_copy_params(_mx_s)

                self._mx_assign_params(_mx_s, Term, Rate)
                _mx_s._mx_roots.extend(self._mx_roots)
                _mx_s._mx_roots.append(_mx_root)

            self._mx_itemspaces[_mx_key] = _mx_root
            return _mx_root



    def __getitem__(self, item):
        return self.__call__(*item)


    def __delitem__(self, item):
        del self._mx_itemspaces[item]



